package ru.fifth.horror.item;
import net.minecraft.entity.player.PlayerEntity;import net.minecraft.item.Item;import net.minecraft.item.ItemUsageContext;import net.minecraft.text.Text;import net.minecraft.util.ActionResult;import ru.fifth.horror.FifthMod;import ru.fifth.horror.block.CassetteDriveBlockEntity;
public final class TvLinkToolItem extends Item{public TvLinkToolItem(Settings s){super(s);}@Override public ActionResult useOnBlock(ItemUsageContext c){PlayerEntity p=c.getPlayer();if(p==null)return ActionResult.PASS;var state=c.getWorld().getBlockState(c.getBlockPos());if(c.getWorld().isClient)return (state.isOf(FifthMod.TELEVISION)||state.isOf(FifthMod.CASSETTE_DRIVE))?ActionResult.SUCCESS:ActionResult.PASS;var n=c.getStack().getOrCreateNbt();if(state.isOf(FifthMod.TELEVISION)){n.putLong("FivenTvPos",c.getBlockPos().asLong());p.sendMessage(Text.literal("§8[§cFiven§8] §7Телевизор выбран: §f"+c.getBlockPos().toShortString()),true);return ActionResult.SUCCESS;}if(state.isOf(FifthMod.CASSETTE_DRIVE)&&c.getWorld().getBlockEntity(c.getBlockPos()) instanceof CassetteDriveBlockEntity d){if(!n.contains("FivenTvPos")){p.sendMessage(Text.literal("§cСначала выбери телевизор."),true);return ActionResult.SUCCESS;}d.linkTv(net.minecraft.util.math.BlockPos.fromLong(n.getLong("FivenTvPos")));d.setPlaybackMode(p.isSneaking()?1:0);p.sendMessage(Text.literal("§7Кассетовод связан с TV. Режим: "+(p.isSneaking()?"§fэкран телевизора":"§fэкран игрока")),true);return ActionResult.SUCCESS;}return ActionResult.PASS;}}
